import math
from functools import lru_cache


@lru_cache(maxsize=None)
def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)


def factorial_digit_count(n):
    """Return the number of digits in n! without computing n! itself."""
    if n < 0:
        raise ValueError("n must be non-negative")
    if n <= 1:
        return 1
    # digits in x = floor(log10(x)) + 1
    # log10(n!) = sum(log10(k) for k in 1..n)
    return math.floor(sum(math.log10(k) for k in range(2, n + 1))) + 1
